//! The standalone host's diagram definitions, as its add dialog offers them (etalii.adp spec 030, Story 5 scenario 1,
//! FR-021, task T068).
//!
//! The standalone host's add dialog lists the `DiagramDefinition`s its modules declare, identity-only modules
//! included, with each one's title, description and icon, and writes a new document from its extension and subject.
//! `catalogue/definitions.json` is that list at 8b6ccfc, generated by `tools/generate-definitions.py` from the modules'
//! sources. The tool-type catalogue ([`crate::Catalogue`]) says what the desktop host can open; this says what the
//! add dialog offers and what it writes.

use serde::Deserialize;

/// The standalone host's definitions, as `tools/generate-definitions.py` writes them.
const STANDALONE: &str = include_str!("../catalogue/definitions.json");

/// What a diagram is: its document, or the folder its registration sits in.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Subject {
    Document,
    Folder,
}

/// On which bodies the standalone host suggests a reading when a file is added as a diagram (`SuggestsBody`).
#[derive(Debug, Clone, PartialEq, Eq, Default, Deserialize)]
pub struct Suggests {
    /// A body is suggested when it contains one of these, case kept.
    #[serde(default)]
    pub contains: Vec<String>,
    /// A body is suggested when it has a Markdown heading of one of these words, ignoring case.
    #[serde(default)]
    pub heading: Vec<String>,
}

impl Suggests {
    /// Whether `text` is a body this reading is worth offering for.
    pub fn suggests(&self, text: &str) -> bool {
        self.contains.iter().any(|marker| text.contains(marker.as_str()))
            || (!self.heading.is_empty() && text.lines().any(|line| self.is_heading(line)))
    }

    /// `^\s{0,3}#{1,6}\s+(word)\s*#*\s*$`, ignoring case, as the standalone host's agent behaviour test reads a line.
    fn is_heading(&self, line: &str) -> bool {
        let indent = line.len() - line.trim_start().len();
        let rest = line.trim_start();
        if indent > 3 {
            return false;
        }
        let hashes = rest.len() - rest.trim_start_matches('#').len();
        let rest = &rest[hashes..];
        if !(1..=6).contains(&hashes) || !rest.starts_with(char::is_whitespace) {
            return false;
        }
        let text = rest.trim().trim_end_matches('#').trim_end();
        self.heading.iter().any(|word| text.eq_ignore_ascii_case(word))
    }
}

/// One diagram definition of the standalone host.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Definition {
    /// `<vendor>/<type>`, or `<vendor>/<type>/<subtype>`.
    pub origin: String,
    pub title: String,
    pub description: String,
    /// A Material Design Icons class.
    pub icon: String,
    /// The extension, dot included, of the body beside the registration; empty when the registration is the whole
    /// diagram.
    pub extension: String,
    pub shared_extension: bool,
    pub alternate_extension: String,
    pub subject: Subject,
    #[serde(default)]
    pub suggests_body: Option<Suggests>,
}

impl Definition {
    /// The vendor segment of the origin.
    pub fn vendor(&self) -> &str {
        self.origin.split('/').next().unwrap_or_default()
    }

    /// The type segment of the origin.
    pub fn type_name(&self) -> &str {
        self.origin.split('/').nth(1).unwrap_or_default()
    }

    /// The subtype segment of the origin; empty when it has none.
    pub fn subtype(&self) -> &str {
        self.origin.split('/').nth(2).unwrap_or_default()
    }

    /// What a registration's first line says it is (`ToolOrigin.MimeType`): the origin, its subtype after a `+`.
    pub fn mime_type(&self) -> String {
        match self.subtype() {
            "" => self.origin.clone(),
            subtype => format!("{}/{}+{subtype}", self.vendor(), self.type_name()),
        }
    }

    /// Whether the body is a file of its own beside the registration.
    pub fn has_document_sibling(&self) -> bool {
        !self.extension.is_empty()
    }

    /// Whether the diagram is the folder its registration sits in.
    pub fn has_folder_subject(&self) -> bool {
        self.subject == Subject::Folder
    }

    /// Whether the add on a file offers this definition for a body reading `text`: yes, unless it has a test.
    pub fn suggests(&self, text: impl FnOnce() -> Option<String>) -> bool {
        match &self.suggests_body {
            None => true,
            Some(test) => text().is_some_and(|t| test.suggests(&t)),
        }
    }
}

#[derive(Deserialize)]
struct Listing {
    definitions: Vec<Definition>,
}

/// Every diagram definition of the standalone host, in the order of its module folders.
pub fn standalone() -> Vec<Definition> {
    let listing: Listing =
        serde_json::from_str(STANDALONE).expect("catalogue/definitions.json is the generator's JSON");
    listing.definitions
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_definition_of_the_standalone_host_is_listed_with_its_title_from_its_catalogue() {
        let definitions = standalone();
        assert_eq!(definitions.len(), 78);
        let catalogue = crate::Catalogue::standalone();
        for definition in &definitions {
            let listed = catalogue.by_origin(&definition.origin).expect("in docs/tools.md");
            assert_eq!(definition.title, listed.display_name, "{}", definition.origin);
        }
    }

    #[test]
    fn the_folder_subjects_and_the_readings_suggested_by_their_bodies_are_kept() {
        let definitions = standalone();
        let of = |origin: &str| definitions.iter().find(|d| d.origin == origin).unwrap();
        assert!(of("helm/chart").has_folder_subject());
        assert!(of("ansible/structure").has_folder_subject());
        assert!(!of("c4/code").has_document_sibling());
        assert_eq!(of("generic/timeline").extension, ".tml");
        assert_eq!(of("generic/timeline").mime_type(), "generic/timeline");
        assert!(of("w3c/owl").suggests(|| Some("<> a owl:Ontology .".into())));
        assert!(!of("w3c/owl").suggests(|| Some("<> a <x> .".into())));
        assert!(of("w3c/rdf").suggests(|| None));
        let abm = of("etalii/agent-behavior-modelling");
        assert!(abm.suggests(|| Some("# Agent\r\n\r\n## Behaviour ##\r\n".into())));
        assert!(!abm.suggests(|| Some("# Agent\n\nBehaviour\n".into())));
    }
}
